// The fake layer of the agent's unit tests: returns prepared results per
// call and records every call with its arguments.
import type { PendingModal, Result, TabsData } from '@src/browser-control';
import type { HandoverRequest, HostPort, LayerPort } from '../ports';

export type FakeHandler = (args: Record<string, unknown>, index: number) => Result | Promise<Result>;

export class FakeLayer implements LayerPort {
  readonly calls: Array<{ tool: string; args: Record<string, unknown>; at: number }> = [];
  readonly started: string[] = [];
  #handlers: Record<string, FakeHandler>;
  #counts = new Map<string, number>();
  tabsData: TabsData = {
    tabs: [{ tabId: 1, url: 'chrome://newtab/', title: 'New Tab', active: true }],
    activeTabId: 1,
  };
  pending = new Map<number, PendingModal[]>();
  revs = new Map<number, number>([[1, 3]]);

  constructor(handlers: Record<string, FakeHandler> = {}) {
    this.#handlers = handlers;
  }

  async call(tool: string, args: Record<string, unknown>): Promise<Result> {
    this.started.push(tool);
    const n = this.#counts.get(tool) ?? 0;
    this.#counts.set(tool, n + 1);
    this.calls.push({ tool, args, at: this.calls.length });
    const handler = this.#handlers[tool];
    return handler ? handler(args, n) : ok(`${tool} · ok`);
  }

  async tabs(): Promise<TabsData> {
    return this.tabsData;
  }

  tabInfo(tabId: number) {
    return { rev: this.revs.get(tabId) ?? 0, pending: this.pending.get(tabId) ?? [] };
  }

  wrap(text: string): string {
    return `<<<page-content 000000000000>>>\n${text}\n<<<end-page-content 000000000000>>>`;
  }
}

export function ok(text: string, extra: Partial<Result> = {}): Result {
  return { ok: true, text, ...extra };
}

export function receipt(extra: Partial<NonNullable<Result['receipt']>> = {}): NonNullable<Result['receipt']> {
  return {
    action: 'click',
    mechanism: 'pointer',
    dispatched: true,
    effect: { verdict: 'changed', signals: ['1 mutation'] },
    ...extra,
  };
}

export function failed(code: string, message = code, extra: Partial<NonNullable<Result['error']>> = {}): Result {
  return {
    ok: false,
    text: `error ${code}\n${message}`,
    error: { code: code as never, message, delivered: false, hint: '', ...extra },
  };
}

export class FakeHost implements HostPort {
  readonly handovers: HandoverRequest[] = [];
  answer: 'given-back' | 'cancelled' = 'given-back';

  async handover(request: HandoverRequest): Promise<'given-back' | 'cancelled'> {
    this.handovers.push(request);
    return this.answer;
  }
}

// Scripted-model helpers for the agent's tests: the summary call of compaction has no tools, so a script tells it apart
// from the agent's turns and numbers only the agent's turns.
import type { ScriptedCall, ScriptedReply } from '@src/llm';

export const SCRIPTED_SUMMARY =
  '## Progress\nRead the pages.\n## Data gathered\nNone.\n## Key decisions\nNone.\n## Next steps\nContinue.';

export function isSummaryCall(call: ScriptedCall): boolean {
  return call.tools.length === 0;
}

/** Answers summary calls with `summary` and passes the agent's turns to `script`, counted from 0. */
export function withSummaries(
  script: (call: ScriptedCall, turn: number) => ScriptedReply,
  summary: string | ((call: ScriptedCall) => ScriptedReply) = SCRIPTED_SUMMARY,
): (call: ScriptedCall) => ScriptedReply {
  let turn = 0;
  return call => {
    if (isSummaryCall(call)) return typeof summary === 'string' ? { text: summary } : summary(call);
    return script(call, turn++);
  };
}

// Settings → Providers: saving a key lists the models, and a key the provider refuses says so at once. A model is tested
// when it is added. On a local endpoint (the fixture server is at localhost)
// adding reads only the model's API, with no chat request; Test models then runs the probes. What the API said is
// stored as `fromApi`.
import { defineCheck } from './registry';
import { sleep, waitForLoad } from './helpers';
import { FIXTURE_PROVIDER } from './panel-chat';
import { FIXTURE_ORIGIN } from '../fixtures-config';

const options = (op: string, extra: Record<string, unknown> = {}) =>
  chrome.runtime.sendMessage({ nbTest: 'options', op, ...extra }) as Promise<{ ok: boolean }>;
const LLM = `${FIXTURE_ORIGIN}/__llm`;

interface StoredModel {
  name: string;
  fromApi?: { contextWindow?: number; vision?: boolean; reasons?: boolean };
  noToolCalling?: boolean;
}

const model = async (name: string) =>
  (
    (await chrome.storage.local.get('nb.providers'))['nb.providers'] as Array<{ models: StoredModel[] }>
  )[0]?.models.find(m => m.name === name);
const chatRequests = async () => ((await (await fetch(`${LLM}/requests`)).json()) as unknown[]).length;

async function until(test: () => Promise<boolean>, ms = 5000): Promise<boolean> {
  for (const end = Date.now() + ms; Date.now() < end; await sleep(100)) if (await test()) return true;
  return false;
}

defineCheck({
  name: 'providers-test',
  title: 'A model tested when it is added',
  description:
    "Saves a key the fake model refuses and checks that the refusal shows, then clears it, saves a good key and checks that the models are listed. Types a model name and checks the note that says to click Add, which goes once it is added. Adds the model on a local endpoint and checks that its API's facts are stored with no chat request, then presses Test models and checks that the probes ran.",
  async run() {
    await fetch(`${LLM}/reset`, { method: 'POST' }).catch(() => undefined);
    await chrome.storage.local.set({ 'nb.providers': [{ ...FIXTURE_PROVIDER, models: [] }] });
    const tab = await chrome.tabs.create({ url: chrome.runtime.getURL('/options.html#providers'), active: true });
    const report: Record<string, unknown> = {};
    try {
      await waitForLoad(tab.id!);
      await sleep(600);
      const body = async () => ((await options('read')) as unknown as { body: string }).body;
      const saveKey = async (text: string) => {
        // The fixture endpoint is not a preset, so its key is optional.
        await options('fill', { label: 'API key (if the server needs one)', text });
        await sleep(200);
        await options('click', { label: 'Save key' });
      };
      await saveKey('wrong-key');
      report.keyRefused = await until(async () => (await body()).includes('did not accept this key'));
      // A saved key cannot be edited, only cleared, before another is typed.
      await options('click', { label: 'Clear key' });
      await sleep(200);
      await saveKey('good-key');
      report.listedOnSave = await until(async () => (await body()).includes('models listed'));
      const before = await chatRequests();
      await options('fill', { label: 'Add a model', text: 'fixture-model-info' });
      await sleep(200);
      report.addHint = (await body()).includes('Click Add to save this model.');
      await options('click', { label: 'Add' });
      await sleep(200);
      report.addHintGone = !(await body()).includes('Click Add to save this model.');
      report.apiRead = await until(async () => (await model('fixture-model-info'))?.fromApi?.contextWindow === 65536);
      const added = await model('fixture-model-info');
      report.fromApi = added?.fromApi;
      report.noChatOnAdd = (await chatRequests()) === before;
      await options('click', { label: 'Test models' });
      report.probed = await until(async () => (await model('fixture-model-info'))?.noToolCalling !== undefined, 10_000);
      report.chatOnTest = (await chatRequests()) > before;
    } finally {
      await chrome.tabs.remove(tab.id!).catch(() => undefined);
      await chrome.storage.local.remove(['nb.providers', 'nb.keys']);
    }
    const fromApi = report.fromApi as StoredModel['fromApi'];
    const ok =
      report.keyRefused === true &&
      report.addHint === true &&
      report.addHintGone === true &&
      report.listedOnSave === true &&
      report.apiRead === true &&
      fromApi?.vision === true &&
      fromApi.reasons === true &&
      report.noChatOnAdd === true &&
      report.probed === true &&
      report.chatOnTest === true;
    if (!ok) throw new Error(`providers-test: ${JSON.stringify(report)}`);
    return report;
  },
});

// The probe's isolated worlds, one per frame and document, and node resolution into them.
import { LayerError } from '../protocol/errors';
import { PROBE_SOURCE, PROBE_WORLD_NAME } from '../probe';
import type { ProbeApi } from '../probe';
import type { CdpPort, FrameRecord } from './ports';

interface RemoteObject {
  objectId?: string;
  value?: unknown;
  description?: string;
}

interface CallResult {
  result: RemoteObject;
  exceptionDetails?: { text: string; exception?: { description?: string } };
}

type ProbeMethod = Exclude<keyof ProbeApi, 'version'>;

/** A node passed to a probe method by its object ID in the same world. */
export class NodeArg {
  constructor(readonly objectId: string) {}
}

export class ProbeClient {
  /** Execution context of the probe world, by `${frameId}|${loaderId}`. */
  #worlds = new Map<string, Promise<number>>();

  constructor(private readonly cdp: CdpPort) {}

  #key(frame: FrameRecord): string {
    return `${frame.frameId}|${frame.loaderId}`;
  }

  /** The probe world of the frame's current document, created and installed on first use. */
  context(frame: FrameRecord): Promise<number> {
    const key = this.#key(frame);
    let world = this.#worlds.get(key);
    if (!world) {
      world = this.#create(frame);
      this.#worlds.set(key, world);
      world.catch(() => this.#worlds.delete(key));
      // Worlds of earlier documents of this frame are gone with them.
      for (const k of this.#worlds.keys()) if (k.startsWith(`${frame.frameId}|`) && k !== key) this.#worlds.delete(k);
    }
    return world;
  }

  async #create(frame: FrameRecord): Promise<number> {
    const { executionContextId } = await this.cdp.send<{ executionContextId: number }>(
      frame.sessionId,
      'Page.createIsolatedWorld',
      { frameId: frame.frameId, worldName: PROBE_WORLD_NAME, grantUniversalAccess: false },
    );
    const installed = await this.cdp.send<CallResult>(frame.sessionId, 'Runtime.evaluate', {
      expression: PROBE_SOURCE,
      contextId: executionContextId,
      returnByValue: true,
    });
    if (installed.exceptionDetails) throw new Error(`Probe install failed: ${installed.exceptionDetails.text}`);
    return executionContextId;
  }

  /** Brings a node into the probe world. A node that is gone is NODE_DETACHED. */
  async resolve(frame: FrameRecord, backendNodeId: number): Promise<string> {
    const attempt = async () => {
      const executionContextId = await this.context(frame);
      const { object } = await this.cdp.send<{ object: RemoteObject }>(frame.sessionId, 'DOM.resolveNode', {
        backendNodeId,
        executionContextId,
      });
      if (!object.objectId) throw new Error('no object');
      return object.objectId;
    };
    try {
      return await attempt();
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (/context/i.test(message)) {
        // The world went away (for example a same-loader reload of the context); recreate once.
        this.#worlds.delete(this.#key(frame));
        try {
          return await attempt();
        } catch {
          // fall through
        }
      }
      throw new LayerError('NODE_DETACHED', `The element is no longer in the page (${message})`);
    }
  }

  /** Calls a probe method with the node as its first argument. Arguments wrapped as `{ objectId }` pass nodes. */
  async call<T>(frame: FrameRecord, objectId: string, method: ProbeMethod, ...args: unknown[]): Promise<T> {
    const response = await this.cdp.send<CallResult>(frame.sessionId, 'Runtime.callFunctionOn', {
      objectId,
      functionDeclaration: `function (...args) { return globalThis.__nbProbe[${JSON.stringify(method)}](this, ...args); }`,
      arguments: args.map(value => (value instanceof NodeArg ? { objectId: value.objectId } : { value })),
      returnByValue: true,
      awaitPromise: true,
    });
    if (response.exceptionDetails) {
      throw new Error(
        `Probe ${method} failed: ${response.exceptionDetails.exception?.description ?? response.exceptionDetails.text}`,
      );
    }
    return response.result.value as T;
  }

  /** Calls a probe method that returns an element, and gives that element's backend node ID (or null). */
  async callForNode(frame: FrameRecord, objectId: string, method: ProbeMethod): Promise<number | null> {
    const response = await this.cdp.send<CallResult>(frame.sessionId, 'Runtime.callFunctionOn', {
      objectId,
      functionDeclaration: `function () { return globalThis.__nbProbe[${JSON.stringify(method)}](this); }`,
      returnByValue: false,
    });
    const node = response.result.objectId;
    if (!node) return null;
    try {
      const { node: described } = await this.cdp.send<{ node: { backendNodeId: number } }>(
        frame.sessionId,
        'DOM.describeNode',
        {
          objectId: node,
        },
      );
      return described.backendNodeId;
    } finally {
      await this.release(frame, node);
    }
  }

  /** Calls a probe method that takes no node. */
  async callGlobal<T>(frame: FrameRecord, method: ProbeMethod, ...args: unknown[]): Promise<T> {
    const contextId = await this.context(frame);
    const response = await this.cdp.send<CallResult>(frame.sessionId, 'Runtime.evaluate', {
      expression: `globalThis.__nbProbe[${JSON.stringify(method)}](...${JSON.stringify(args)})`,
      contextId,
      returnByValue: true,
      awaitPromise: true,
    });
    if (response.exceptionDetails) throw new Error(`Probe ${method} failed: ${response.exceptionDetails.text}`);
    return response.result.value as T;
  }

  /** The focused element of the frame's document, when the document has focus and it is not a frame or body. */
  async focusedIn(frame: FrameRecord): Promise<{ objectId: string; backendNodeId: number } | null> {
    const contextId = await this.context(frame);
    const response = await this.cdp.send<CallResult>(frame.sessionId, 'Runtime.evaluate', {
      expression:
        "(() => { if (!document.hasFocus()) return null; const el = globalThis.__nbProbe.focused(); return el && !['IFRAME', 'FRAME', 'BODY', 'HTML'].includes(el.tagName) ? el : null; })()",
      contextId,
      returnByValue: false,
    });
    const objectId = response.result.objectId;
    if (!objectId) return null;
    const { node } = await this.cdp.send<{ node: { backendNodeId: number } }>(frame.sessionId, 'DOM.describeNode', {
      objectId,
    });
    return { objectId, backendNodeId: node.backendNodeId };
  }

  async release(frame: FrameRecord, objectId: string): Promise<void> {
    await this.cdp.send(frame.sessionId, 'Runtime.releaseObject', { objectId }).catch(() => undefined);
  }

  /** Forgets every world (the tab detached). */
  reset(): void {
    this.#worlds.clear();
  }
}

// The navigation policy: Nanobrowser's isUrlAllowed (src/background/browser/util.ts at ad47282),
// unchanged in its rules: schemes that are always blocked, then a deny list and an allow list of domains or exact URLs.
// Product sessions add a list of blocked sites, matched with siteOf.
import { siteOf } from './site';

export interface UrlPolicy {
  allow: string[];
  deny: string[];
  /**
   * Blocked sites, matched with `siteOf`: the exact host, so a row covers the same addresses as an Allow or Ask row.
   * The deny and allow lists keep their own rules for the test panel.
   */
  blocked?: string[];
}

export const EMPTY_POLICY: UrlPolicy = { allow: [], deny: [], blocked: [] };

/** A site as a user may type it ("Example.com", "https://www.example.com/x", "localhost:3000"), as `siteOf` keys it. */
export function siteKey(entry: string): string {
  const e = entry.trim();
  if (!e) return '';
  return siteOf(/^[a-z][a-z0-9+.-]*:\/\//i.test(e) ? e : `http://${e}`);
}

/** Whether an address loads a blocked site: its own site, or for a blob: URL the site that made it. */
export function isBlockedSite(url: string, blocked: readonly string[] | undefined): boolean {
  if (!blocked?.length) return false;
  const trimmed = url.trim();
  const site = siteOf(trimmed.toLowerCase().startsWith('blob:') ? trimmed.slice(5) : trimmed);
  return !!site && blocked.includes(site);
}

/** Blocked whatever the lists say. */
const DANGEROUS_PREFIXES = [
  'https://chromewebstore.google.com', // scripts are not allowed to be injected into the Chrome Web Store
  'chrome-extension://',
  'chrome://',
  'javascript:',
  'data:',
  'file:',
  'vbscript:',
  'ws:',
  'wss:',
];

export function isUrlAllowed(url: string, allowList: string[], denyList: string[]): boolean {
  const trimmedUrl = url.trim();
  if (trimmedUrl.length === 0) return false;
  const lowerCaseUrl = trimmedUrl.toLowerCase();
  if (DANGEROUS_PREFIXES.some(prefix => lowerCaseUrl.startsWith(prefix))) return false;
  if (allowList.length === 0 && denyList.length === 0) return true;
  // A blob: URL belongs to the origin that created it; judge it by that origin (its hostname would be empty).
  if (lowerCaseUrl.startsWith('blob:')) return isUrlAllowed(trimmedUrl.slice(5), allowList, denyList);
  if (trimmedUrl === 'about:blank') return true;
  try {
    const parsedUrl = new URL(trimmedUrl);
    const urlWithoutProtocol = lowerCaseUrl.replace(/^https?:\/\//, '');
    for (const deniedEntry of denyList) if (urlWithoutProtocol === deniedEntry) return false;
    for (const allowedEntry of allowList) if (urlWithoutProtocol === allowedEntry) return true;
    // A fully qualified name ("example.com.") is the same host as the name without its last dot.
    let domain = parsedUrl.hostname.toLowerCase().replace(/\.$/, '');
    const portIndex = domain.indexOf(':');
    if (portIndex > -1 && !domain.startsWith('[')) domain = domain.substring(0, portIndex);
    for (const deniedEntry of denyList) {
      if (domain === deniedEntry || domain.endsWith(`.${deniedEntry}`)) return false;
    }
    for (const allowedEntry of allowList) {
      if (domain === allowedEntry || domain.endsWith(`.${allowedEntry}`)) return true;
    }
    return allowList.length === 0;
  } catch {
    return false;
  }
}

/** Normalises list entries as the user types them: lower case, no scheme, no trailing slash. */
export function normalizePolicy(policy: UrlPolicy): UrlPolicy {
  const clean = (list: string[]) => [
    ...new Set(
      list
        .map(e =>
          e
            .trim()
            .toLowerCase()
            .replace(/^https?:\/\//, '')
            .replace(/\/$/, '')
            // A bare host written with its last dot ("example.com.") is the host without it, as in isUrlAllowed.
            .replace(/^([^/]+)\.$/, '$1'),
        )
        .filter(Boolean),
    ),
  ];
  return {
    allow: clean(policy.allow),
    deny: clean(policy.deny),
    blocked: [...new Set((policy.blocked ?? []).map(siteKey).filter(Boolean))],
  };
}

export function allows(policy: UrlPolicy, url: string): boolean {
  return !isBlockedSite(url, policy.blocked) && isUrlAllowed(url, policy.allow, policy.deny);
}

/** Layer 3 runs only when a list is configured; the always-blocked schemes are covered by layers 1, 2 and 4. */
export function hasLists(policy: UrlPolicy): boolean {
  return policy.allow.length > 0 || policy.deny.length > 0 || (policy.blocked?.length ?? 0) > 0;
}

/** The most restrictive combination: a URL passes only if every policy allows it. */
export function combinePolicies(policies: UrlPolicy[]): (url: string) => boolean {
  return url => policies.every(p => allows(p, url)) && isUrlAllowed(url, [], []);
}

// Raw CDP commands through chrome.debugger, sent to the session of a frame that Puppeteer reports.
// Elements are never reached through Puppeteer; every element command goes through here.
import { LayerError } from '../protocol/errors';

/** The pseudo session ID ExtensionTransport gives the page target. chrome.debugger addresses it with no sessionId. */
export const PAGE_SESSION_ALIAS = 'pageTargetSessionId';

/** Session ID as the layer uses it: undefined for the tab's root session. */
export function normalizeSessionId(sessionId: string | undefined): string | undefined {
  return sessionId === PAGE_SESSION_ALIAS ? undefined : sessionId;
}

/** @deprecated name kept for the step 0.2 spike; use normalizeSessionId. */
export const toDebuggerSessionId = normalizeSessionId;

export class CdpCommandError extends Error {
  constructor(
    readonly method: string,
    message: string,
  ) {
    super(`${method}: ${message}`);
    this.name = 'CdpCommandError';
  }
}

/** A command that did not answer in time. It cannot be cancelled, so its outcome is unknown. */
export class CdpTimeoutError extends Error {
  constructor(
    readonly method: string,
    readonly timeoutMs: number,
  ) {
    super(`${method}: no answer within ${timeoutMs} ms`);
    this.name = 'CdpTimeoutError';
  }
}

/** Timeouts: 10 s for captures, 5 s otherwise. */
export const DEFAULT_COMMAND_TIMEOUT_MS = 5_000;
export const CAPTURE_TIMEOUT_MS = 10_000;

/** Sends one command. `cancel`, when it settles first, rejects the command (used for detach). */
export async function sendRaw<T = unknown>(
  tabId: number,
  sessionId: string | undefined,
  method: string,
  params: object = {},
  timeoutMs = DEFAULT_COMMAND_TIMEOUT_MS,
  cancel?: Promise<never>,
): Promise<T> {
  const target: chrome.debugger.DebuggerSession = { tabId };
  const debuggerSessionId = normalizeSessionId(sessionId);
  if (debuggerSessionId) target.sessionId = debuggerSessionId;

  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new CdpTimeoutError(method, timeoutMs)), timeoutMs);
  });
  try {
    const command = chrome.debugger
      .sendCommand(target, method, params as Record<string, unknown>)
      .catch((error: unknown) => {
        const message = error instanceof Error ? error.message : String(error);
        if (/not attached|Detached while handling command|No tab with given id/i.test(message)) {
          throw new LayerError('DEBUGGER_DETACHED', `${method}: ${message}`, { delivered: 'unknown' });
        }
        throw new CdpCommandError(method, message);
      });
    return (await Promise.race(cancel ? [command, timeout, cancel] : [command, timeout])) as T;
  } finally {
    clearTimeout(timer);
  }
}

