// Permissions in the extension: the mode belongs to the conversation, the site rules are one map in chrome.storage, and
// the layer asks `decideWrite` for each classified write.
// Blocked sites go into every agent session's navigation policy.
import type { WriteDecision, WriteQuestion } from '@src/browser-control';
import { decideWrite, siteRulesStorage } from '@src/store/settings';
import type { SiteRuleEntry } from '@src/store/settings';
import type { PermissionMode } from '@src/store/types';

export class Permissions {
  #rules: Record<string, SiteRuleEntry> = {};
  #listeners = new Set<() => void>();

  constructor() {
    void siteRulesStorage.get().then(rules => this.#set(rules));
    siteRulesStorage.subscribe(() => this.#set(siteRulesStorage.getSnapshot() ?? {}));
  }

  #set(rules: Record<string, SiteRuleEntry>): void {
    const blockedBefore = this.blockedSites().join('\n');
    this.#rules = rules;
    if (this.blockedSites().join('\n') !== blockedBefore) this.#listeners.forEach(l => l());
  }

  /** Called when the blocked list changes, so open sessions get the new policy. */
  onBlockedChange(listener: () => void): () => void {
    this.#listeners.add(listener);
    return () => this.#listeners.delete(listener);
  }

  async ready(): Promise<void> {
    this.#set(await siteRulesStorage.get());
  }

  blockedSites(): string[] {
    return Object.entries(this.#rules)
      .filter(([, e]) => e.rule === 'block')
      .map(([site]) => site);
  }

  /** The answer to the layer for a classified write. */
  decide(mode: PermissionMode, question: WriteQuestion): WriteDecision {
    // A page with no host cannot hold a rule: a write there asks every time, in both modes.
    if (!question.site) return { decision: 'ask', canRemember: false };
    const entry = this.#rules[question.site];
    const rule = entry?.rule === 'allow' || entry?.rule === 'ask' ? entry.rule : undefined;
    const decision = decideWrite(mode, rule);
    return { decision, by: rule ? 'site-rule' : 'auto', canRemember: rule !== 'ask' };
  }

  /** "Allow on this site". */
  async allow(site: string): Promise<void> {
    const now = new Date().toISOString();
    await siteRulesStorage.set(rules => ({ ...rules, [site]: { rule: 'allow', setAt: now } }));
  }
}

// Provider factories, ported from the current Nanobrowser's src/background/llm/providers.ts and reduced to the
// providers of the first release. The loop runs tools itself, so a model handle is only a model, its call settings and
// its provider options.
import { createAnthropic } from '@ai-sdk/anthropic';
import { createGoogle } from '@ai-sdk/google';
import { createOpenAI } from '@ai-sdk/openai';
import type { LanguageModel } from 'ai';

export type ProviderKind =
  'anthropic' | 'openai' | 'gemini' | 'openai-compatible' | 'ollama' | 'lmstudio' | 'openrouter';

/** Everything needed to call one model. The key is passed in; src/llm never reads storage. */
export interface ModelSpec {
  kind: ProviderKind;
  modelName: string;
  apiKey?: string;
  baseUrl?: string;
  maxOutputTokens?: number;
  /** For a local server: at most this many requests at once to it. */
  maxConcurrent?: number;
}

export type ProviderOptions = Record<string, Record<string, unknown>>;

export interface ChatModel {
  spec: ModelSpec;
  model: LanguageModel;
  providerOptions?: ProviderOptions;
  /** The cost of the latest response, when the provider reports one the SDK does not pass on (OpenRouter). */
  takeCost?: () => Promise<number | undefined>;
}

export interface CreateModelOptions {
  /** Custom fetch, used by tests to inspect requests. */
  fetch?: typeof fetch;
}

export const DEFAULT_BASE_URLS: Partial<Record<ProviderKind, string>> = {
  ollama: 'http://localhost:11434/v1',
  lmstudio: 'http://localhost:1234/v1',
  openrouter: 'https://openrouter.ai/api/v1',
};

/**
 * The kinds that speak chat completions at a base URL. Their servers may refuse `reasoning_effort`, which the run's
 * fallback handles, and Test models probes them for reasoning.
 */
export const CHAT_COMPLETIONS_KINDS: readonly ProviderKind[] = [
  'openai-compatible',
  'ollama',
  'lmstudio',
  'openrouter',
];

/**
 * The OpenAI-compatible endpoint of an Ollama or LM Studio server: `/v1` is added unless the address ends with it,
 * so the user can type the server's address (ported).
 */
export function openAICompatibleBaseUrl(kind: ProviderKind, baseUrl?: string): string | undefined {
  const fallback = DEFAULT_BASE_URLS[kind];
  // OpenRouter's address is fixed: the card has no field for it.
  if (kind === 'openrouter') return fallback;
  const url = (baseUrl?.trim() || fallback)?.replace(/\/+$/, '');
  if (!url) return undefined;
  if (kind === 'ollama' || kind === 'lmstudio') return url.endsWith('/v1') ? url : `${url}/v1`;
  return url;
}

export function createModel(spec: ModelSpec, options: CreateModelOptions = {}): ChatModel {
  const { kind, modelName, apiKey } = spec;
  const fetch = options.fetch;
  switch (kind) {
    case 'anthropic': {
      const anthropic = createAnthropic({
        apiKey,
        ...(spec.baseUrl ? { baseURL: spec.baseUrl } : {}),
        // The service worker sends an Origin header, so Anthropic requires this opt-in for browser access.
        headers: { 'anthropic-dangerous-direct-browser-access': 'true' },
        fetch,
      });
      // The prompt cache, switched on for the whole request: the API places the breakpoint itself.
      return {
        spec,
        model: anthropic(modelName),
        providerOptions: { anthropic: { cacheControl: { type: 'ephemeral' } } },
      };
    }
    case 'gemini': {
      const google = createGoogle({ apiKey, ...(spec.baseUrl ? { baseURL: spec.baseUrl } : {}), fetch });
      return { spec, model: google(modelName) };
    }
    case 'openai': {
      // The Responses API: GPT-6 models refuse function tools with reasoning on chat completions. Nothing is stored
      // at OpenAI; each turn sends the whole history, and tool calls go back without item ids. The SDK detects the
      // reasoning models itself.
      const openai = createOpenAI({ apiKey, ...(spec.baseUrl ? { baseURL: spec.baseUrl } : {}), fetch });
      return {
        spec,
        model: openai.responses(modelName),
        providerOptions: { openai: { strictJsonSchema: false, store: false } },
      };
    }
    default: {
      // Ollama, LM Studio, OpenRouter and any other OpenAI-compatible server: chat completions at the base URL.
      const accounting = kind === 'openrouter' ? usageAccounting(fetch ?? globalThis.fetch) : null;
      const openai = createOpenAI({
        apiKey: apiKey || kind,
        baseURL: openAICompatibleBaseUrl(kind, spec.baseUrl),
        ...(kind === 'openrouter'
          ? { headers: { 'HTTP-Referer': 'https://nanobrowser.ai', 'X-Title': 'Nanobrowser' } }
          : {}),
        // OpenRouter reports a request's cost in its usage when asked.
        fetch: accounting?.fetch ?? fetch,
      });
      return {
        spec,
        model: openai.chat(modelName),
        providerOptions: { openai: { strictJsonSchema: false } },
        ...(accounting ? { takeCost: accounting.takeCost } : {}),
      };
    }
  }
}

/**
 * OpenRouter's usage accounting: each request asks for it, and the cost in the final usage chunk is read from a copy of
 * the stream, because the SDK's schema does not keep it.
 */
export function usageAccounting(base: typeof fetch): {
  fetch: typeof fetch;
  takeCost: () => Promise<number | undefined>;
} {
  let latest: Promise<number | undefined> = Promise.resolve(undefined);
  const wrapped: typeof fetch = async (input, init) => {
    if (typeof init?.body === 'string') {
      try {
        const body = JSON.parse(init.body) as Record<string, unknown>;
        init = { ...init, body: JSON.stringify({ ...body, usage: { include: true } }) };
      } catch {
        // Not JSON: sent as it is.
      }
    }
    const response = await base(input, init);
    if (!response.body) return response;
    const [forSdk, forCost] = response.body.tee();
    latest = (async () => {
      const reader = forCost.getReader();
      const decoder = new TextDecoder();
      let text = '';
      let cost: number | undefined;
      for (;;) {
        const { done, value } = await reader.read().catch(() => ({ done: true, value: undefined }));
        if (done) break;
        text += decoder.decode(value, { stream: true });
        const lines = text.split('\n');
        text = lines.pop() ?? '';
        for (const line of lines) {
          const found = /"usage"\s*:\s*\{[^}]*"cost"\s*:\s*([0-9.eE+-]+)/.exec(line)?.[1];
          if (found !== undefined && Number.isFinite(Number(found))) cost = Number(found);
        }
      }
      return cost;
    })();
    return new Response(forSdk, {
      status: response.status,
      statusText: response.statusText,
      headers: response.headers,
    });
  };
  return {
    fetch: wrapped,
    takeCost: async () => {
      const cost = await latest;
      latest = Promise.resolve(undefined);
      return cost;
    },
  };
}

// Settings → Permissions: the microphone, the browser features (Chrome permissions the user allows here), then the
// one site list: what Allow, Ask and Block do, then each site set to
// one of them, with the date it was set and a remove icon, and adding a site by hand. Nothing here allows payments,
// access grants or secrets. The default mode is in Settings → General.
import { Fragment, useState } from 'react';
import { siteRulesStorage } from '@src/store/settings';
import type { SiteRule, SiteRuleEntry } from '@src/store/settings';
import { Button, Input, Notice, Select } from '@src/ui/components';
import { BrowserFeaturesCard } from './BrowserFeaturesCard';
import { MicrophoneCard } from './MicrophoneCard';
import { SettingsCard } from './SettingsCard';
import { useStorage } from '@src/ui/hooks';
import { t } from '@src/ui/i18n';
import { TrashIcon } from '@src/ui/icons';

const EMPTY: Record<string, SiteRuleEntry> = {};

/** The three rules, each with what it does, listed above the sites. */
const RULES = [
  ['perm.allow', 'perm.allowHint'],
  ['perm.ask', 'perm.askHint'],
  ['perm.block', 'perm.blockHint'],
] as const;

/**
 * The site key of what the user typed: a host or an address. The same rules as the layer's `siteOf` (lower case,
 * no trailing dot, no leading `www.`, the port when not the default); a unit test keeps the two in step.
 */
export function siteFromInput(input: string): string {
  const text = input.trim();
  if (!text) return '';
  try {
    const url = new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(text) ? text : `https://${text}`);
    let host = url.hostname.toLowerCase().replace(/\.$/, '');
    if (host.startsWith('www.')) host = host.slice(4);
    return url.port ? `${host}:${url.port}` : host;
  } catch {
    return '';
  }
}

function date(iso?: string): string {
  return iso ? new Date(iso).toLocaleDateString() : '—';
}

export function PermissionsSection() {
  const rules = useStorage(siteRulesStorage, EMPTY);
  const [site, setSite] = useState('');
  const [rule, setRule] = useState<SiteRule>('allow');
  const [error, setError] = useState(false);
  const sites = Object.entries(rules).sort(([a], [b]) => a.localeCompare(b));
  const setRuleOf = (key: string, value: SiteRule) =>
    siteRulesStorage.set(r => ({ ...r, [key]: { ...r[key], rule: value, setAt: new Date().toISOString() } }));
  return (
    <div className="flex flex-col gap-6">
      <h2 className="sr-only">{t('settings.nav.permissions')}</h2>
      <MicrophoneCard />
      <BrowserFeaturesCard />
      <SettingsCard title={t('perm.sites')} description={t('perm.sitesHint')} className="flex flex-col gap-8">
        <div className="flex flex-col gap-4">
          <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1.5 text-sm">
            {RULES.map(([name, hint]) => (
              <Fragment key={name}>
                <dt className="font-medium">{t(name)}</dt>
                <dd className="text-nb-muted">{t(hint)}</dd>
              </Fragment>
            ))}
          </dl>
          <Notice>{t('perm.neverAllowed')}</Notice>
        </div>
        <div className="flex flex-col gap-4">
          {sites.length ? (
            <table className="w-full text-sm">
              <thead className="text-left text-xs text-nb-muted">
                <tr>
                  <th className="pb-2 font-normal">{t('perm.site')}</th>
                  <th className="pb-2 font-normal">{t('perm.rule')}</th>
                  <th className="pb-2 font-normal">{t('perm.setAt')}</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {sites.map(([key, entry]) => (
                  <tr key={key} className="border-t border-nb-border">
                    <td className="py-2 font-mono">{key}</td>
                    <td className="py-2">
                      <Select
                        aria-label={t('perm.ruleFor', { site: key })}
                        value={entry.rule}
                        onChange={e => void setRuleOf(key, e.target.value as SiteRule)}>
                        <option value="allow">{t('perm.allow')}</option>
                        <option value="ask">{t('perm.ask')}</option>
                        <option value="block">{t('perm.block')}</option>
                      </Select>
                    </td>
                    <td className="py-2 text-xs">{date(entry.setAt)}</td>
                    <td className="py-2 text-right">
                      <button
                        type="button"
                        className="rounded-md p-1.5 text-nb-muted hover:bg-nb-surface hover:text-nb-fg focus-visible:outline focus-visible:outline-2 focus-visible:outline-nb-accent"
                        aria-label={t('perm.removeSite', { site: key })}
                        title={t('perm.removeSite', { site: key })}
                        onClick={() =>
                          void siteRulesStorage.set(r => {
                            const next = { ...r };
                            delete next[key];
                            return next;
                          })
                        }>
                        <TrashIcon size={16} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : null}
          <form
            className="flex flex-wrap items-center gap-2"
            onSubmit={e => {
              e.preventDefault();
              const key = siteFromInput(site);
              setError(!key);
              if (!key) return;
              void siteRulesStorage.set(r => ({ ...r, [key]: { rule, setAt: new Date().toISOString() } }));
              setSite('');
            }}>
            <Input
              aria-label={t('perm.addSite')}
              placeholder="example.com"
              value={site}
              onChange={e => setSite(e.target.value)}
              className="w-64"
            />
            <Select aria-label={t('perm.rule')} value={rule} onChange={e => setRule(e.target.value as SiteRule)}>
              <option value="allow">{t('perm.allow')}</option>
              <option value="ask">{t('perm.ask')}</option>
              <option value="block">{t('perm.block')}</option>
            </Select>
            <Button type="submit" variant="primary" className="ml-4">
              {t('perm.add')}
            </Button>
            {error ? <span className="text-xs text-red-700 dark:text-red-300">{t('perm.badSite')}</span> : null}
          </form>
        </div>
      </SettingsCard>
    </div>
  );
}

